import type { AssetInspection } from './asset-inspection-model';
import type { AuditSection } from './audit-section-model';
import type { Question } from './question-model';

export interface InspectionResponse {
  /**
   * @displayName Inspection Response ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Inspection Response Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  inspectionResponseName: string;
  /**
   * @displayName Asset Inspection
   */
  assetInspection?: Pick<AssetInspection, 'id' | 'assetInspectionName'>;
  /**
   * @displayName Audit Section
   * @validationRule Required for create/update operations
   */
  auditSection: Pick<AuditSection, 'id' | 'auditSectionName'>;
  /**
   * @displayName Created Date
   * @validationRule Required for create/update operations
   */
  createdDate: string;
  /**
   * @displayName Is Deficiency
   * @validationRule Required for create/update operations
   */
  isDeficiency: boolean;
  /**
   * @displayName Modified Date
   * @validationRule Required for create/update operations
   */
  modifiedDate: string;
  /**
   * @displayName Question
   * @validationRule Required for create/update operations
   */
  question: Pick<Question, 'id' | 'questionName'>;
  /**
   * @displayName Question Code Snapshot
   * @validationRule Required for create/update operations
   */
  questionCodeSnapshot: string;
  /**
   * @displayName Question Text Snapshot
   * @validationRule Required for create/update operations
   */
  questionTextSnapshot: string;
  /**
   * @displayName Response Value
   */
  responseValue?: string;
}

export const _InspectionResponse = 'InspectionResponse' as const;